        "back": "المتطابقة المثلثية تكون صحيحة لجميع قيم المتغير التي يكون عندها طرفا المعادلة معرّفين (عدد لا نهائي من الحلول يمثل كامل المجال المعرّف)، بينما المعادلة المثلثية الاعتيادية تكون صحيحة فقط لقيم محددة وخاصة للمتغير (مثل حلول محددة في دورة واحدة أو فترات معينة).",
