        "back": "يتم ذلك بتمثيل الطرف الأيسر كاقتران y = sin x tan x والطرف الأيمن كاقتران y = sec x - cos x بيانيًا. إذا تطابق المنحنيان تماماً على شاشة الرسم البياني لجميع القيم المعرفة، فإن ذلك يثبت بيانيًا أن المعادلة صحيحة لجميع قيم المتغير، مما يحقق تعريف المتطابقة المثلثية.",
