        "front": "ما هي الصيغة الرياضية لمتطابقة جيب ضعف الزاوية ($\\sin 2\\theta$)؟",
        "back": "متطابقة جيب ضعف الزاوية هي صيغة مثلثية تُعبّر عن جيب ضعف الزاوية بدلالة جيب الزاوية وجيب تمامها، وتُكتب رياضياً على الصورة: $\\sin 2\\theta = 2 \\sin \\theta \\cos \\theta$. مثال: إذا كان $\\sin \\theta = \\frac{3}{5}$ و $\\cos \\theta = -\\frac{4}{5}$، فإن $\\sin 2\\theta = 2(\\frac{3}{5})(-\\frac{4}{5}) = -\\frac{24}{25}$.",
        "level": "Easy"
