        "front": "ما هي متطابقة فيثاغورس الأساسية التي يُعتمد عليها كخطوة أولى لإيجاد قيمة جيب تمام الزاوية ($\\cos \\theta$) تمهيداً للتعويض في متطابقة جيب ضعف الزاوية؟",
        "back": "متطابقة فيثاغورس الأساسية المستخدمة هي: $\\sin^2 \\theta + \\cos^2 \\theta = 1$. وتُستخدم لإيجاد قيمة $\\cos \\theta$ عندما تكون قيمة $\\sin \\theta$ معلومة (أو العكس)، مع مراعاة إشارة الربع الذي تقع فيه الزاوية لتحديد الإشارة النهائية لجيب التمام.",
