        "back": "أولاً: نستخدم متطابقة فيثاغورس ($\\sin^2 \\theta + \\cos^2 \\theta = 1$) لإيجاد قيمة $\\cos \\theta$ مع تحديد إشارتها (+ أو -) بناءً على الربع الذي تقع فيه الزاوية $\\theta$.\nثانياً: نُعوّض قيمتي $\\sin \\theta$ و $\\cos \\theta$ في متطابقة جيب ضعف الزاوية: $\\sin 2\\theta = 2 \\sin \\theta \\cos \\theta$ للحصول على القيمة الدقيقة.",
