        "back": "بما أن $\\theta$ في الربع الثاني، فإن جيب التمام سالب. نجد $\\cos \\theta = -\\sqrt{1 - \\sin^2 \\theta} = -\\sqrt{1 - \\frac{9}{25}} = -\\frac{4}{5}$.\nبتطبيق متطابقة جيب ضعف الزاوية: \n$\\sin 2\\theta = 2 \\sin \\theta \\cos \\theta = 2 \\left(\\frac{3}{5}\\right)\\left(-\\frac{4}{5}\\right) = -\\frac{24}{25}$.",
