        "back": "1) نجد الإحداثي $a$ باستخدام نظرية فيثاغورس: $a^2 + 3^2 = 5^2 \\implies a^2 = 16 \\implies a = -4$ (سالب لأن النقطة في الربع الثاني).\n2) نحدد النسب المثلثية: $\\sin \\theta = \\frac{3}{5}$ و $\\cos \\theta = \\frac{a}{5} = -\\frac{4}{5}$.\n3) نطبق متطابقة جيب ضعف الزاوية: $\\sin 2\\theta = 2 \\sin \\theta \\cos \\theta = 2 \\left(\\frac{3}{5}\\right)\\left(-\\frac{4}{5}\\right) = -\\frac{24}{25}$.",
