        "back": "نلاحظ أن المقدار يماثل صيغة متطابقة جيب ضعف الزاوية حيث $\\theta = 3x$. \nبإعادة كتابة المقدار: $4 \\sin(3x) \\cos(3x) = 2 [2 \\sin(3x) \\cos(3x)]$.\nبتطبيق المتطابقة $\\sin 2\\theta = 2 \\sin \\theta \\cos \\theta$، يصبح المقدار: $2 \\sin(2 \\times 3x) = 2 \\sin(6x)$.",
