        "back": "من حيث عدد الصيغ المكافئة المباشرة:\n- لمتطابقة جيب ضعف الزاوية صيغة واحدة فقط وهي: $\\sin 2\\theta = 2 \\sin \\theta \\cos \\theta$.\n- لمتطابقة جيب تمام ضعف الزاوية ثلاث صيغ مكافئة وهي: $\\cos^2 \\theta - \\sin^2 \\theta$، و $1 - 2\\sin^2 \\theta$، و $2\\cos^2 \\theta - 1$.",
