        "back": "البدء بالطرف الأيسر:\n1) $\\csc 2\\theta = \\frac{1}{\\sin 2\\theta}$ (باستخدام متطابقة المقلوب).\n2) بالتعويض عن جيب ضعف الزاوية: $\\csc 2\\theta = \\frac{1}{2 \\sin \\theta \\cos \\theta}$.\n3) بفصل الكسر: $\\csc 2\\theta = \\frac{1}{2} \\cdot \\frac{1}{\\cos \\theta} \\cdot \\frac{1}{\\sin \\theta}$.\n4) باستخدام متطابقات المقلوب ($\\sec \\theta = \\frac{1}{\\cos \\theta}$ و $\\csc \\theta = \\frac{1}{\\sin \\theta}$)، نحصل على الطرف الأيمن: $\\frac{1}{2} \\sec \\theta \\csc \\theta$. وهو المطلوب.",
